from pathlib import Path

root = Path.cwd()
def replace_line(file, prefix, new):
    path = root / file
    lines = path.read_text(encoding='utf-8-sig').splitlines()
    matches = [i for i, line in enumerate(lines) if line.startswith(prefix)]
    if len(matches) != 1:
        raise ValueError(f'{file}: expected one prefix {prefix}, got {len(matches)}')
    lines[matches[0]] = new
    path.write_text('\n'.join(lines) + '\n', encoding='utf-8')

def append(file, text):
    path = root / file
    path.write_text(path.read_text(encoding='utf-8-sig').rstrip() + '\n\n' + text.strip() + '\n', encoding='utf-8')

